  }
}

{
  "name": "rush-commands",
  "private": true,
  "dependencies": {
    "@rushstack/rush-sdk": "^5.150.0",
    "concurrently": "^9.2.1"
  }
}

{
  "name": "@flowgram.ai/test-run-plugin",
  "version": "0.1.8",
  "homepage": "https://flowgram.ai/",
  "repository": "https://github.com/bytedance/flowgram.ai",
  "license": "MIT",
  "exports": {
    "types": "./dist/index.d.ts",
    "import": "./dist/esm/index.js",
    "require": "./dist/index.js"
  },
  "main": "./dist/index.js",
  "module": "./dist/esm/index.js",
  "types": "./dist/index.d.ts",
  "scripts": {
    "build": "npm run build:fast -- --dts-resolve",
    "build:fast": "tsup src/index.ts --format cjs,esm --sourcemap --legacy-output",
    "build:watch": "npm run build:fast -- --dts-resolve",
    "clean": "rimraf dist",
    "test": "exit 0",
    "test:cov": "exit 0",
    "ts-check": "tsc --noEmit",
    "watch": "npm run build:fast -- --dts-resolve --watch --ignore-watch dist"
  },
  "dependencies": {
    "inversify": "^6.0.1",
    "nanoid": "^5.0.9",
    "zustand": "^4.5.5",
    "@flowgram.ai/form-core": "workspace:*",
    "@flowgram.ai/core": "workspace:*",
    "@flowgram.ai/utils": "workspace:*",
    "@flowgram.ai/document": "workspace:*",
    "@flowgram.ai/form": "workspace:*",
    "@flowgram.ai/reactive": "workspace:*"
  },
  "devDependencies": {
    "react": "^18",
    "@types/react": "^18",
    "@flowgram.ai/eslint-config": "workspace:*",
    "@flowgram.ai/ts-config": "workspace:*",
    "tsup": "^8.0.1",
    "typescript": "^5.8.3"
  },
  "peerDependencies": {
    "react": ">=16.8"
  },
  "peerDependenciesMeta": {
    "react": {
      "optional": true
    }
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}

